// Some portions generated by Claude
package org.eclipse.rdf4j.sail.memory;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.TreeMap;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.model.vocabulary.RDFS;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.TupleQueryResult;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

/**
 * LATERAL substitutes the left row's bindings into its right-hand side, so an OPTIONAL there is evaluated with those
 * values even when its optional part is the only place that mentions them. This is the SPARQL 1.2 compliance case
 * {@code lateral-02} (LateralTest#testLateralWithOptional): three left rows must yield three result rows, two of them
 * extended with the LIMIT 1 label of *their own* subject.
 */
class LateralOptionalSubSelectTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final String PREFIX = "PREFIX ex: <http://example.org/>\n"
			+ "PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\n";

	private SailRepository repository;

	@BeforeEach
	void setUp() {
		repository = new SailRepository(new MemoryStore());
		repository.init();
		add(ex("subject1"), ex("predicate"), ex("object1"));
		add(ex("subject1"), RDFS.LABEL, VF.createLiteral("Label 1"));
		add(ex("subject2"), ex("predicate"), ex("object2"));
		add(ex("subject2"), RDFS.LABEL, VF.createLiteral("Label 2"));
		add(ex("subject3"), ex("predicate"), ex("object3"));
	}

	@AfterEach
	void tearDown() {
		repository.shutDown();
	}

	private static IRI ex(String local) {
		return VF.createIRI("http://example.org/" + local);
	}

	@Test
	void lateralOptionalOverLimitedSubSelectKeepsEveryLeftRow() {
		String query = PREFIX + """
				SELECT * {
				   ?s ex:predicate ?o
				   LATERAL { OPTIONAL { SELECT * { ?s rdfs:label ?label } LIMIT 1 } }
				}
				""";
		assertThat(rows(query)).containsExactly(
				"{label=Label 1, o=http://example.org/object1, s=http://example.org/subject1}",
				"{label=Label 2, o=http://example.org/object2, s=http://example.org/subject2}",
				"{o=http://example.org/object3, s=http://example.org/subject3}");
	}

	@Test
	void lateralOptionalOverProjectedSubSelectKeepsEveryLeftRow() {
		String query = PREFIX + """
				SELECT ?s ?o ?label {
				   ?s ex:predicate ?o
				   LATERAL { OPTIONAL { SELECT ?s ?label { ?s rdfs:label ?label } ORDER BY ?label LIMIT 1 } }
				}
				""";
		assertThat(rows(query)).containsExactly(
				"{label=Label 1, o=http://example.org/object1, s=http://example.org/subject1}",
				"{label=Label 2, o=http://example.org/object2, s=http://example.org/subject2}",
				"{o=http://example.org/object3, s=http://example.org/subject3}");
	}

	@Test
	void lateralOptionalOverPatternKeepsEveryLeftRow() {
		String query = PREFIX + """
				SELECT * {
				   ?s ex:predicate ?o
				   LATERAL { OPTIONAL { ?s rdfs:label ?label } }
				}
				""";
		assertThat(rows(query)).containsExactly(
				"{label=Label 1, o=http://example.org/object1, s=http://example.org/subject1}",
				"{label=Label 2, o=http://example.org/object2, s=http://example.org/subject2}",
				"{o=http://example.org/object3, s=http://example.org/subject3}");
	}

	@Test
	void lateralOptionalWithConditionOverSubSelectKeepsEveryLeftRow() {
		String query = PREFIX + """
				SELECT * {
				   ?s ex:predicate ?o
				   LATERAL { OPTIONAL { { SELECT * { ?s rdfs:label ?label } LIMIT 1 } FILTER(BOUND(?label)) } }
				}
				""";
		assertThat(rows(query)).containsExactly(
				"{label=Label 1, o=http://example.org/object1, s=http://example.org/subject1}",
				"{label=Label 2, o=http://example.org/object2, s=http://example.org/subject2}",
				"{o=http://example.org/object3, s=http://example.org/subject3}");
	}

	@Test
	void lateralOptionalConditionSeesTheSubstitutedInput() {
		// ?o is substituted in the whole LATERAL right-hand side, the OPTIONAL condition included.
		String query = PREFIX + """
				SELECT * {
				   ?s ex:predicate ?o
				   LATERAL { OPTIONAL { ?s ex:predicate ?y FILTER(?y = ?o) } }
				}
				""";
		assertThat(rows(query)).containsExactly(
				"{o=http://example.org/object1, s=http://example.org/subject1, y=http://example.org/object1}",
				"{o=http://example.org/object2, s=http://example.org/subject2, y=http://example.org/object2}",
				"{o=http://example.org/object3, s=http://example.org/subject3, y=http://example.org/object3}");
	}

	@Test
	void optionalOverLimitedSubSelectOutsideLateralKeepsBottomUpSemantics() {
		// Without LATERAL the sub-select is a scope boundary: LIMIT 1 picks one label for the whole query, which is
		// compatible with subject1 only; the other rows stay bare.
		String query = PREFIX + """
				SELECT * {
				   ?s ex:predicate ?o
				   OPTIONAL { SELECT * { ?s rdfs:label ?label } ORDER BY ?label LIMIT 1 }
				}
				""";
		assertThat(rows(query)).containsExactly(
				"{label=Label 1, o=http://example.org/object1, s=http://example.org/subject1}",
				"{o=http://example.org/object2, s=http://example.org/subject2}",
				"{o=http://example.org/object3, s=http://example.org/subject3}");
	}

	private void add(IRI subject, IRI predicate, Value object) {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.add(subject, predicate, object);
		}
	}

	private List<String> rows(String query) {
		List<String> rows = new ArrayList<>();
		try (SailRepositoryConnection connection = repository.getConnection();
				TupleQueryResult result = connection.prepareTupleQuery(query).evaluate()) {
			while (result.hasNext()) {
				BindingSet bindingSet = result.next();
				TreeMap<String, String> sorted = new TreeMap<>();
				for (String name : bindingSet.getBindingNames()) {
					Value value = bindingSet.getValue(name);
					if (value != null) {
						sorted.put(name, value.stringValue());
					}
				}
				rows.add(sorted.toString());
			}
		}
		rows.sort(Comparator.naturalOrder());
		return rows;
	}
}
